// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListForms Lista os formularios do usuario autenticado
	// (GET /admin/forms)
	ListForms(ctx context.Context, request ListFormsRequestObject) (ListFormsResponseObject, error)
	// CreateForm Cria um formulario dinamico como rascunho
	// (POST /admin/forms)
	CreateForm(ctx context.Context, request CreateFormRequestObject) (CreateFormResponseObject, error)
	// DeleteForm Exclui logicamente um formulario do usuario autenticado
	// (DELETE /admin/forms/{formId})
	DeleteForm(ctx context.Context, request DeleteFormRequestObject) (DeleteFormResponseObject, error)
	// GetForm Busca um formulario do usuario autenticado para edicao
	// (GET /admin/forms/{formId})
	GetForm(ctx context.Context, request GetFormRequestObject) (GetFormResponseObject, error)
	// UpdateForm Atualiza um formulario em rascunho
	// (PUT /admin/forms/{formId})
	UpdateForm(ctx context.Context, request UpdateFormRequestObject) (UpdateFormResponseObject, error)
	// PublishForm Publica um formulario em rascunho
	// (POST /admin/forms/{formId}/publish)
	PublishForm(ctx context.Context, request PublishFormRequestObject) (PublishFormResponseObject, error)
	// ListFormSubmissions Lista as respostas de um formulario do usuario autenticado
	// (GET /admin/forms/{formId}/submissions)
	ListFormSubmissions(ctx context.Context, request ListFormSubmissionsRequestObject) (ListFormSubmissionsResponseObject, error)
	// BeginGoogleLogin Inicia o login com Google
	// (GET /auth/google)
	BeginGoogleLogin(ctx context.Context, request BeginGoogleLoginRequestObject) (BeginGoogleLoginResponseObject, error)
	// CompleteGoogleLogin Finaliza o login com Google
	// (GET /auth/google/callback)
	CompleteGoogleLogin(ctx context.Context, request CompleteGoogleLoginRequestObject) (CompleteGoogleLoginResponseObject, error)
	// Logout Encerra a sessao atual
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// RegisterUser Cadastra um usuario com e-mail e inicia sua sessao
	// (POST /auth/register)
	RegisterUser(ctx context.Context, request RegisterUserRequestObject) (RegisterUserResponseObject, error)
	// GetAuthSession Retorna o usuario autenticado
	// (GET /auth/session)
	GetAuthSession(ctx context.Context, request GetAuthSessionRequestObject) (GetAuthSessionResponseObject, error)
	// ListPublishedForms Lista os formularios publicados disponiveis para respostas
	// (GET /forms)
	ListPublishedForms(ctx context.Context, request ListPublishedFormsRequestObject) (ListPublishedFormsResponseObject, error)
	// GetPublicForm Busca um formulario publicado pelo slug
	// (GET /forms/{slug})
	GetPublicForm(ctx context.Context, request GetPublicFormRequestObject) (GetPublicFormResponseObject, error)
	// CreateSubmission Valida e salva respostas de um formulario publicado
	// (POST /forms/{slug}/submissions)
	CreateSubmission(ctx context.Context, request CreateSubmissionRequestObject) (CreateSubmissionResponseObject, error)
	// GetHealth Consulta a saude da API
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

